enewalConsumeCommand,\\n)\\nfrom aos_api.aip_budget_policy_renewal_connection import (\\n    ProtectedRenewalConfig,open_purpose_connection,\\n)\\nfrom aos_api.aip_budget_policy_renewal_identity import _database_identity,authenticate_checker\\nfrom aos_api.aip_budget_policy_renewal_store import RenewalAuthorityStore,RenewalStoreBlocked\\nfrom aos_api.aip_network_issuer_attempt import (\\n    AttemptReceipt,AttemptAlreadyRecorded,AttemptConflict,AttemptUnknown,_reserve_attempt_receipt,\\n)\\n\\nCOMMANDS={'propose':RenewalProposalCommand,'decide':RenewalDecisionCommand,\\n          'revoke':RenewalRevocationCommand,'consume':RenewalConsumeCommand}\\nPURPOSES={'propose':'maker','decide':'issuer','revoke':'issuer','consume':'consumer'}\\n\\n\\nclass RenewalServiceBlocked(ValueError):\\n    pass\\n\\n\\nclass RenewalRequest(AipContractModel):\\n    model_config=ConfigDict(frozen=True)\\n    schema_version: Literal[1]\\n    mode: Literal['execute','reconcile']\\n    operation: Literal['propose','decide','revoke','consume']\\n    command: RenewalProposalCommand|RenewalDecisionCommand|RenewalRevocationCommand|RenewalConsumeCommand\\n    bearer_token: SecretStr|None=None\\n\\n    @model_validator(mode='before')\\n    @classmethod\\n    def public_identity_fields(cls,value):\\n        if (type(value) is dict and value.get('operation') not in {'decide','revoke'}\\n                and any(key in value for key in ('bearerToken','bearer_token'))):\\n            raise ValueError('machine token field forbidden')\\n        return value\\n\\n    @field_validator('schema_version',mode='before')\\n    @classmethod\\n    def version(cls,value):\\n        if type(value) is not int:\\n            raise ValueError('exact version required')\\n        return value\\n\\n    @field_validator('command',mode='before')\\n    @classmethod\\n    def exact_command(cls,value,info):\\n        expected=COMMANDS.get(info.data.get('operation'))\\n        if expected is None:\\n            raise ValueError('operation required')\\n        if type(value) is expected:\\n            value=value.model_dump(mode='python',by_alias=True)\\n        if type(value) is not dict:\\n            raise ValueError('exact command required')\\n        return expected.model_validate(value)\\n\\n    @field_validator('bearer_token',mode='before')\\n    @classmethod\\n    def secret(cls,value):\\n        if value is None:\\n            return None\\n        if type(value) is SecretStr:\\n            value=value.get_secret_value()\\n        if type(value) is not str or not 0<len(value)<=16384:\\n            raise ValueError('bounded token required')\\n        return SecretStr(value)\\n\\n    @model_validator(mode='after')\\n    def identity_kind(self):\\n        if type(self.command) is not COMMANDS[self.operation]:\\n            raise ValueError('command operation mismatch')\\n        if (self.operation in {'decide','revoke'})!=(self.bearer_token is not None):\\n            raise ValueError('issuer token required; machine token forbidden')\\n        return self\\n\\n    def revalidated(self):\\n        excluded={'bearer_token'} if self.bearer_token is None else set()\\n        return type(self).model_validate(self.model_dump(mode='python',by_alias=True,exclude=excluded))\\n\\n\\ndef protocol_schema():\\n    schema=RenewalRequest.model_json_schema(by_alias=True)\\n    schema['$id']='aos.budget-policy-renewal.ipc/v1'\\n    metadata={\\n        'operation':{'type':'string','enum':list(COMMANDS)},\\n        'requestHash':{'type':'string','pattern':'^[0-9a-f]{64}$'},\\n        'activationEligible':{'type':'boolean','const':False},\\n    }\\n    schema['$defs']['RenewalResponseFrame']={\\n        'type':'object','additionalProperties':False,\\n        'required':['schemaVersion','operation','requestHash','activationEligible','result'],\\n        'properties':{'schemaVersion':{'type':'integer','const':1},**metadata,\\n            'result':{'type':'object','additionalProperties':True,\\n                '$comment':'Native SQL artifact fields remain governed by A Store and independent readonly history.',\\n                'required':['operation','requestHash','activationEligible','status'],\\n                'properties':{**metadata,'status':{'type':'string','enum':[\\n                    'prepared','decided','revoked','observed','unresolved','conflict','blocked']}}}},\\n        'allOf':[{'if':{'properties':{'operation':{'const':operation}},'required':['operation']},\\n            'then':{'properties':{'result':{'properties':{'operation':{'const':operation}}}}}}\\n            for operation in COMMANDS],\\n    }\\n    schema['allOf']=[]\\n    for operation,command in COMMANDS.items():\\n        then={'properties':{'command':{'$ref':'#/$defs/'+command.__name__}}}\\n        if operation in {'decide','revoke'}:\\n            then['required']=['bearerToken']\\n            then['properties']['bearerToken']={'type':'string','minLength':1,'maxLength':16384}\\n        else:\\n            then['not']={'required':['bearerToken']}\\n        schema['allOf'].append({'if':{'properties':{'operation':{'const':operation}},'required':['operation']},'then':then})\\n    return schema\\n\\n\\nclass RenewalService:\\n    def __init__(self,config,attempt_directory):\\n        if type(config) is not ProtectedRenewalConfig or not Path(attempt_directory).is_absolute():\\n            raise RenewalServiceBlocked('RENEWAL_PRIVATE_SERVICE_REQUIRED')\\n        self.config=config\\n        self.attempt_directory=Path(attempt_directory)\\n\\n    def reconcile(self,request):\\n        request=request.revalidated()\\n        purpose=PURPOSES[request.operation]\\n        with open_purpose_connection(self.config,purpose,True) as conn:\\n            store=RenewalAuthorityStore(conn,checker_binding=self.config.binding)\\n            return store.reconcile(request.command,token=request.bearer_token)\\n\\n    def execute(self,request):\\n        if type(request) is not RenewalRequest:\\n            raise RenewalServiceBlocked('RENEWAL_EXACT_PRIVATE_REQUEST_REQUIRED')\\n        request=request.revalidated()\\n        if request.mode=='reconcile':\\n            return self.reconcile(request)\\n        purpose=PURPOSES[request.operation]\\n        # Current authentication precedes reservation; A rechecks in its write tx.\\n        with open_purpose_connection(self.config,purpose,True) as conn:\\n            with conn.transaction():\\n                conn.execute('SET TRANSACTION ISOLATION LEVEL READ COMMITTED, READ ONLY')\\n                conn.execute(\\\"SELECT set_config('aos.org_id','org-org',true),set_config('aos.project_id','dev-project',true)\\\")\\n                login=_database_identity(conn,purpose)\\n                subject=('postgres-service:'+login if purpose!='issuer' else\\n                         authenticate_checker(request.bearer_token,binding=self.config.binding,conn=conn).subject)\\n        command=request.command\\n        identifier=(command.source_policy_id if request.operation=='propose' else command.proposal_id)\\n        marker=AttemptReceipt(command.org_id,command.project_id,identifier,\\n                              command.idempotency_key,command.request_hash,subject)\\n        try:\\n            _reserve_attempt_receipt(self.attempt_directory,marker,\\n                                    namespace='budget-policy-renewal/v1/'+request.operation)\\n        except AttemptAlreadyRecorded:\\n            return self.reconcile(request)\\n        except AttemptConflict:\\n            return self._history_status(request,'conflict')\\n        except AttemptUnknown:\\n            return self._history_status(request,'unresolved')\\n        # No exception can cause another execute call after the marker exists.\\n        try:\\n            with open_purpose_connection(self.config,purpose,False) as conn:\\n                store=RenewalAuthorityStore(conn,checker_binding=self.config.binding)\\n                if purpose=='issuer':\\n                    return getattr(store,request.operation)(command,token=request.bearer_token)\\n                return getattr(store,request.operation)(command)\\n        except RenewalStoreBlocked:\\n            # Confirmed rollback/pre-write refusal is not an unknown COMMIT.\\n            # The durable marker still prevents a later automatic execute.\\n            return self._history_status(request,'blocked')\\n        except Exception:\\n            try:\\n                return self.reconcile(request)\\n            except Exception:\\n                return self._history_status(request,'unresolved')\\n\\n    @staticmethod\\n    def _history_status(request,status):\\n        return {'operation':request.operation,'requestHash':request.command.request_hash,\\n                'status':status,'activationEligible':False}\\n\\nFULL CURRENT SOURCE services/aos-api/tests/aip/test_budget_policy_renewal_service.py\\n\\\"\\\"\\\"Pure B envelope/schema tests; no identity/PG acceptance inferred here.\\\"\\\"\\\"\\nimport json\\nfrom pathlib import Path\\nimport pytest\\nfrom aos_api.aip_budget_policy_renewal_service import RenewalRequest,protocol_schema\\nfrom aos_api.aip_budget_policy_renewal_contracts import (\\n    RenewalDecisionCommand,RenewalConsumeCommand,RenewalRevocationCommand,\\n)\\n\\n\\ndef envelope(operation,**extra):\\n    c={'schemaVersion':1,'orgId':'org-org','projectId':'dev-project','idempotencyKey':'fixture-service',\\n       'proposalId':'fixture-proposal','proposalHash':'a'*64}\\n    if operation=='decide':c.update(targetActiveHash='b'*64,decision='approved')\\n    else:c.update(decisionId='fixture-decision',decisionHash='b'*64)\\n    if operation=='revoke':c['reasonCode']='approval_withdrawn'\\n    body={'schemaVersion':1,'mode':'execute','operation':operation,'command':c}\\n    if operation in {'decide','revoke'}:body['bearerToken']='fixture-invalid-token-not-consent'\\n    return {**body,**extra}\\n\\n\\n@pytest.mark.parametrize('op,cls',[('decide',RenewalDecisionCommand),('consume',RenewalConsumeCommand),('revoke',RenewalRevocationCommand)])\\ndef test_exact_operation_and_typed_command_reparse(op,cls):\\n    r=RenewalRequest.model_validate(envelope(op))\\n    assert type(r.command) is cls\\n    assert r.revalidated().command.request_hash==r.command.request_hash\\n\\n\\n@pytest.mark.parametrize('mutation',['boolVersion','wrongCommand','machineToken','machineSnakeToken','issuerMissingToken','extraActor'])\\ndef test_wire_identity_and_discriminator_mutation_rejected(mutation):\\n    body=envelope('consume')\\n    if mutation=='boolVersion':body['schemaVersion']=True\\n    elif mutation=='wrongCommand':body['operation']='decide'\\n    elif mutation=='machineToken':body['bearerToken']=None\\n    elif mutation=='machineSnakeToken':body['bearer_token']=None\\n    elif mutation=='issuerMissingToken':body=envelope('decide');body.pop('bearerToken')\\n    else:body['actor']='forged'\\n    with pytest.raises(ValueError):RenewalRequest.model_validate(body)\\n\\n\\ndef test_generated_json_schema_matches_shipped_schema_and_discriminator():\\n    path=Path(__file__).resolve().parents[2]/'aos_api/aip_budget_policy_renewal_schema.json'\\n    schema=json.loads(path.read_text())\\n    assert schema==protocol_schema()\\n    assert schema['additionalProperties'] is False\\n    assert len(schema['allOf'])==4\\n\\n\\ndef test_generated_schema_includes_closed_native_result_frame():\\n    frame=protocol_schema()['$defs']['RenewalResponseFrame']\\n    assert frame['additionalProperties'] is False\\n    assert set(frame['required'])=={'schemaVersion','operation','requestHash','activationEligible','result'}\\n    properties=frame['properties']\\n    assert properties['schemaVersion']=={'type':'integer','const':1}\\n    assert properties['activationEligible']=={'type':'boolean','const':False}\\n    assert properties['requestHash']['pattern']=='^[0-9a-f]{64}$'\\n    assert set(properties['operation']['enum'])=={'propose','decide','consume','revoke'}\\n    result=properties['result']\\n    assert set(result['required'])=={'operation','requestHash','activationEligible','status'}\\n    assert set(result['properties']['status']['enum'])=={'prepared','decided','revoked','observed','unresolved','conflict','blocked'}\\n\\n\\ndef test_model_copy_cannot_smuggle_actor_or_command_kind():\\n    r=RenewalRequest.model_validate(envelope('consume'))\\n    altered=r.model_copy(update={'operation':'decide'})\\n    with pytest.raises(ValueError):altered.revalidated()\\n\\n\\n# Original fixtures only create data in the explicitly owned disposable DB.\\nfrom tests.aip.test_budget_policy_renewal_pg import schema_database, schema_source as original_schema_source\\n\\n\\n@pytest.fixture(scope='session')\\ndef schema_source(schema_database):\\n    \\\"\\\"\\\"Seed historical fixture facts under admin locks; guards restored pre-commit.\\n\\n    Full migrations prohibit unapproved ACTIVE inserts. This setup is explicitly\\n    fixture history, never an acceptance of human approval or a runtime bypass.\\n    No B operation runs until both original guards are enabled again.\\n    \\\"\\\"\\\"\\n    _,admin=schema_database\\n    source=original_schema_source.__wrapped__(schema_database)\\n    with admin.transaction():\\n        admin.execute(\\\"INSERT INTO public.meta_org(id,name) VALUES('org-org','isolated B fixture org')\\\")\\n        admin.execute(\\\"INSERT INTO public.meta_workspace(org_id,project_id,name) VALUES('org-org','dev-project','isolated B fixture workspace')\\\")\\n        admin.execute('ALTER TABLE public.aip_budget_revision DISABLE TRIGGER aip_budget_active_insert_guard')\\n        admin.execute('ALTER TABLE public.aip_model_governance_policy_revision DISABLE TRIGGER cost_configuration_write_guard')\\n        value=next(source)\\n        admin.execute('SET CONSTRAINTS ALL IMMEDIATE')\\n        admin.execute('ALTER TABLE public.aip_budget_revision ENABLE TRIGGER aip_budget_active_insert_guard')\\n        admin.execute('ALTER TABLE public.aip_model_governance_policy_revision ENABLE TRIGGER cost_configuration_write_guard')\\n    try:yield value\\n    finally:\\n        try:next(source)\\n        except StopIteration:pass\\n\\n\\n@pytest.fixture\\ndef isolated_signed_gateway(schema_source,tmp_path,monkeypatch):\\n    \\\"\\\"\\\"Actual RS256/JWKS in a separate PG network namespace, never real consent.\\\"\\\"\\\"\\n    import os,hashlib,threading,time\\n    import jwt\\n    from cryptography.hazmat.primitives.asymmetric import rsa\\n    from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer\\n    from psycopg.conninfo import conninfo_to_dict\\n    from psycopg import sql\\n    from tests.aip.test_budget_policy_renewal_connection import closed_config\\n    from aos_api.aip_budget_policy_renewal_connection import load_protected_config,_CALLERS,_FORBIDDEN_ENV\\n    if os.environ.get('AOS_RENEWAL_ISOLATED_SIGNER')!='1':\\n        pytest.skip('separate owned network namespace required for fixture signer')\\n    dsn,admin,source,now=schema_source\\n    parts=conninfo_to_dict(dsn)\\n    assert parts['host']=='127.0.0.1' and parts['port']=='5432'\\n    assert parts['dbname'].startswith('aos_test_')\\n    for key in _FORBIDDEN_ENV:monkeypatch.delenv(key,raising=False)\\n    key=rsa.generate_private_key(public_exponent=65537,key_size=2048)\\n    jwk=json.loads(jwt.algorithms.RSAAlgorithm.to_jwk(key.public_key()))\\n    jwk.update(kid='isolated-b-fixture',alg='RS256',use='sig')\\n    requests=[]\\n    class Handler(BaseHTTPRequestHandler):\\n        def do_GET(self):\\n            requests.append(self.path)\\n            if self.path!='/realms/qyh-local/protocol/openid-connect/certs':\\n                self.send_error(404);return\\n            body=json.dumps({'keys':[jwk]}).encode()\\n            self.send_response(200);self.send_header('Content-Type','application/json')\\n            self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)\\n        def log_message(self,*args):pass\\n    server=ThreadingHTTPServer(('127.0.0.1',18448),Handler)\\n    thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()\\n    path,value=closed_config(tmp_path)\\n    seal=admin.execute(\\\"SELECT obj_description('public.aip_budget_policy_renewal_proposal'::regclass,'pg_class')\\\").fetchone()[0]\\n    value['enabled']=True\\n    for purpose,user in _CALLERS.items():\\n        # Fixture-only secret; HBA is SCRAM for callers in the owned test PG.\\n        password='isolated-b-fixture-password'\\n        admin.execute(sql.SQL('ALTER ROLE {} LOGIN PASSWORD {}').format(sql.Identifier(user),sql.Literal(password)))\\n        profile=value['profiles'][purpose]\\n        passfile=Path(profile['passfile'])\\n        passfile.write_text(f\\\"127.0.0.1:5432:{parts['dbname']}:{user}:{password}\\\\n\\\")\\n        profile.update(port=5432,database=parts['dbname'],\\n            passfileSha256=hashlib.sha256(passfile.read_bytes()).hexdigest(),\\n            manifestSha256=hashlib.sha256(seal.encode()).hexdigest())\\n    path.write_text(json.dumps(value))\\n    attempts=tmp_path/'attempts';attempts.mkdir(mode=0o700)\\n    issuer='http://127.0.0.1:18448/realms/qyh-local'\\n    def token(**overrides):\\n        claims={'iss':issuer,'aud':'aos-api','sub':'6f31cfdc-a26c-4f1f-ad6b-95a8559cc657',\\n            'iat':int(time.time()),'exp':int(time.time())+120,\\n            'org_id':'org-org','project_id':'dev-project','roles':['admin']}\\n        claims.update(overrides)\\n        return jwt.encode(claims,key,algorithm='RS256',headers={'kid':'isolated-b-fixture'})\\n    try:yield load_protected_config(path),attempts,token,requests,schema_source\\n    finally:\\n        server.shutdown();server.server_close();thread.join(timeout=3)\\n        for user in _CALLERS.values():\\n            admin.execute(sql.SQL('ALTER ROLE {} NOLOGIN PASSWORD NULL').format(sql.Identifier(user)))\\n\\n\\ndef test_native_private_service_signed_chain